import json
from pathlib import Path

root = Path('.book-work/incompletetribes-v1-e9dde0116308/translations/ro/full/chunks')
translations = {
    't000001': 'Triburi incomplete',
    't000002': 'Triburi incomplete',
    't000003': 'Apartenență, conflict și speranța de a construi o civilizație pentru oameni imperfecți',
    't000004': 'Uneori pare că singurul lucru sănătos care ne-a mai rămas este ca oamenii să refacă triburi în jurul unor idealuri și concepte. Și totuși suntem atât de limitați, atât de plini de nevoi și impulsuri, încât intrăm repede în conflict cu cei din jur. Există vreo ieșire sau vom repeta ciclurile de pace și război până când ne vom distruge singuri? Mai speră oamenii la o lume mai bună sau au renunțat în tăcere la acest ideal?”',
    't000005': 'Cartea începe de aici: nu cu încredere, ci cu întrebarea dacă încrederea mai poate fi apărată din punct de vedere intelectual.',
    't000006': 'Preludiu — Întrebarea din spatele întrebării',
    't000007': 'Întrebarea primejdioasă nu este dacă omenirea este bună. Este dacă putem construi o civilizație care să nu ceară ca oamenii să devină mai întâi buni.',
    't000008': 'Există un anumit fel de epuizare care apare când optimismul politic și tehnologic s-a consumat, dar nevoia omenească de sens rămâne. Privim instituțiile și vedem competență procedurală, dar prea puțină încredere. Privim viața online și vedem conexiuni fără comunitate. Privim ideologiile și găsim, în multe dintre ele, fie limbajul învechit al luptelor din secolul al XX-lea, fie certitudinea fragilă a unor noi facțiuni care se adună cu repeziciune. Sub zgomot stă o bănuială mai tăcută: poate că visul la scară mare a eșuat. Poate că oamenii sunt pur și simplu prea limitați ca să coopereze profund vreme îndelungată fără să transforme cooperarea în excludere, ierarhie, resentiment sau război.',
    't000009': 'Prima ispită este resemnarea. Istoria poate fi citită ca o succesiune de formațiuni, extinderi, schisme, războaie, înțelegeri născute din epuizare și noi formațiuni. Numele se schimbă; tiparul pare cunoscut. Pacea devine normală, apoi este luată drept ceva de la sine înțeles, apoi devine fragilă. O generație care nu a construit o instituție o moștenește fără să înțeleagă prețul plătit pentru ea. Apar noi nemulțumiri, unele reale, altele fabricate. Este propus un nou „noi”. În cele din urmă, cineva descoperă că solidaritatea se creează mai ușor împotriva unui dușman decât în jurul unui proiect comun dificil. Vechiul mecanism revine îmbrăcat în haine moderne.',
    't000010': 'A doua ispită este opusul: să ne imaginăm că atașamentul tribal poate fi eliminat prin educație. Speranța aceasta este nobilă, dar înțelege greșit ce ar dispărea odată cu tribalismul. Oamenii nu doar urăsc în grupuri. Iubim în grupuri, ne sacrificăm în grupuri, construim limbi și laboratoare în grupuri, creștem copii în grupuri, jelim în grupuri, ne amintim în grupuri și transformăm valori abstracte în obiceiuri deoarece cei din jurul nostru tratează acele valori ca fiind reale. Capacitatea de a spune „noi” nu este un defect atașat întâmplător speciei. Este una dintre tehnologiile centrale prin care specia a ajuns să poată duce la capăt proiecte mai mari decât viața unui singur om.',
    't000011': 'Argumentul acestei cărți nu este, așadar, nici antitribal, nici romantic față de triburi. Pornește de la o premisă mai incomodă: probabil că nu putem avea o cooperare umană profundă fără grupuri delimitate și probabil că nu le putem face sigure cerându-le membrilor să fie universaliști morali în fiecare clipă. Sarcina ține de arhitectură. Avem nevoie de forme de apartenență care se pot întări fără să devină totale; de comunități care ne pot cere ceva fără să pretindă totul; de idealuri care pot călăuzi un grup fără să dovedească prin aceasta că toți cei din afara lui sunt corupți, proști, impuri sau dispensabili.',
    't000012': 'Numesc asemenea formațiuni triburi incomplete. Folosesc cuvântul „trib” în mod deliberat, dar metaforic. El nu descrie formele politice indigene, sistemele de rudenie sau o anumită etapă antropologică. Numește orice comunitate delimitată în care identitatea, loialitatea, interacțiunea repetată, normele comune, memoria și scopul comun devin suficient de puternice pentru a schimba comportamentul. Un laborator de cercetare poate deveni tribal în acest sens. La fel și o profesie, o congregație religioasă, o rețea de activiști, un proiect cu sursă deschisă, o unitate militară, o companie, o școală, un cartier sau o națiune. Întrebarea relevantă nu este cum își spune grupul. Întrebarea este cât din persoană încearcă să stăpânească.',
    't000013': 'Un trib complet spune, implicit sau explicit: valoarea ta morală, prietenii tăi, informațiile tale, dușmanii tăi, explicația ta despre istorie, viitorul tău și poate chiar îndoielile tale intime ar trebui să se întâlnească aici. Un trib incomplet refuză această pretenție de întregire. Recunoaște că are cunoaștere parțială, jurisdicție limitată, membri cu mai multe afilieri, norme ce pot fi revizuite și oameni din afară care nu sunt, din acest motiv, dușmani. Poate rămâne totuși exigent. Poate cere curaj, disciplină, sacrificiu, măiestrie sau fidelitate. Dar nu poate pretinde un monopol metafizic.',
    't000014': 'Această distincție contează deoarece problema nu mai este doar filosofică. Tehnologia modernă mărește atât scara coordonării, cât și pe cea a distrugerii. Armele nucleare au făcut ca anumite erori de calcul geopolitic să poată avea un sfârșit definitiv. Biotehnologia și inteligența artificială creează alte domenii în care grupuri mici de oameni pot dobândi capacități cândva rezervate statelor. În același timp, sistemele digitale pot fabrica comunități, dușmani, mituri și sincronizare emoțională mai repede decât puteau societățile anterioare. Vechiul animal uman dobândește instrumente care fac ca vechile sale moduri de a eșua să aibă urmări mai grave.',
    't000015': 'Totuși, fatalismul este și leneș din punct de vedere empiric. Oamenii au construit în repetate rânduri instituții care limitează violența, lărgesc cooperarea și le permit străinilor să coexiste fără afecțiune reciprocă. Datele recente despre conflicte nu justifică o poveste triumfalistă despre progresul inevitabil: războaiele s-au intensificat din nou în mai multe regiuni. Dar nici lunga istorie nu susține afirmația că războiul este un rezultat anual fix al biologiei umane. Conflictul variază enorm între perioade și instituții. În această variație există spațiul civilizației.',
    't000016': 'Scopul paginilor care urmează este să exploreze acest spațiu. Speranța apărată aici este în mod deliberat mai modestă decât utopia și mai ambițioasă decât resemnarea. Este speranța că niște creaturi imperfecte pot proiecta relații între grupuri imperfecte astfel încât niciun eșec să nu devină total. Civilizația, în această viziune, nu înseamnă abolirea triburilor. Este arta de a face fiecare trib incomplet.',
    't000017': 'Partea I — Problema lui „noi”',
    't000018': 'Aparține profund. Condu doar în parte. Lasă loc unei alte lumi.',
    't000019': 'Capitolul 1 — Animalul care spune „noi”',
    't000020': 'Înainte să întrebăm cum scăpăm de tribalism, ar trebui să înțelegem de ce anume am scăpa.',
    't000021': 'Oamenii au o capacitate neobișnuită de a coopera cu persoane care nu le sunt rude, inclusiv cu străini. Acest fapt ne este atât de familiar, încât e ușor să-i ratăm caracterul straniu. Stăm la coadă, plătim impozite, respectăm standarde tehnice, ne supunem evaluării colegiale, contribuim la bunuri publice, urmăm regulile de circulație, ne alăturăm organizațiilor, trimitem bani unor oameni pe care nu i-am întâlnit niciodată și uneori ne riscăm viața pentru oameni cu care nu avem legături genetice. Unei ființe pur individuale, o mare parte din civilizația obișnuită i s-ar părea de neînțeles.',
    't000022': 'Dar cooperarea generalizată se sprijină pe mecanisme psihologice care nu sunt ele însele generalizate. Învățăm norme în locuri anume, de la oameni anume. Acordăm importanță accentelor, ritualurilor, simbolurilor, reputațiilor, uniformelor, poveștilor, glumelor, acreditărilor și experiențelor comune. Cercetările despre identitatea socială au arătat cât de ușor deosebesc oamenii un grup propriu de unul exterior; experimentele clasice cu grupuri minimale au găsit favoritism chiar și atunci când categoriile care îi despărțeau pe participanți erau aproape neînsemnate. Lecția importantă nu este că oamenii sunt în mod natural plini de ură. Este că împărțirea în categorii poate căpăta semnificație pentru comportament cu un conținut material surprinzător de redus.',
    't000023': 'Această distincție contează. Dragostea pentru propriul grup nu este pur și simplu același fenomen ca ura față de grupul din afară. Un grup poate fi foarte unit fără să devină violent față de cei din afară. Dar coeziunea schimbă peisajul moral. Observăm mai ușor sacrificiile alor noștri. Interpretăm mai îngăduitor un comportament ambiguu atunci când vine de la oameni pe care îi considerăm de-ai noștri. Aplicăm normele diferit. Ne amintim rănile selectiv. Grupul devine o lentilă prin care dovezile capătă greutate emoțională.',
    't000024': 'Există o literatură evoluționistă despre ceea ce Choi și Bowles au numit altruism parohial: posibilitatea incomodă ca generozitatea costisitoare față de propriul grup și ostilitatea față de cei din afară să se lege între ele în condiții de conflict între grupuri. Povestea evoluționistă exactă rămâne dezbătută, cum și trebuie. Dar avertismentul conceptual rămâne valabil indiferent de un anumit model. Aceeași persoană poate fi generoasă și crudă fără să simtă vreo contradicție, dacă generozitatea și cruzimea sunt distribuite între cercuri morale diferite.',
}
for filename in ('0001.json', '0002.json'):
    path = root / filename
    data = json.loads(path.read_text(encoding='utf-8'))
    for segment in data['segments']:
        segment['translation'] = translations[segment['id']]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print('Translated 24 full-reader segments')
